create or replace function public.next_order_number() returns text language plpgsql security definer set search_path=public as $$ declare y integer:=extract(year from now())::integer; n integer; begin insert into public.order_number_sequences(year,last_number) values(y,1) on conflict(year) do update set last_number=public.order_number_sequences.last_number+1,updated_at=now() returning last_number into n; return format('ORD-DEB-%s-%s',y,lpad(n::text,4,'0')); end; $$; create or replace function public.archive_order(p_order_id uuid,p_reason text default null) returns public.orders language plpgsql security definer set search_path=public as $$ declare r public.orders; begin if not public.has_staff_role(array['owner','superadmin','super_admin','sales_admin','admin']) then raise exception 'Not authorized'; end if; update public.orders set archived_at=now(),archived_by=auth.uid(),archive_reason=nullif(btrim(coalesce(p_reason,'')),''),updated_by=auth.uid() where id=p_order_id and archived_at is null returning * into r; if not found then raise exception 'Order not found or already archived'; end if; return r; end; $$; create or replace function public.restore_order(p_order_id uuid) returns public.orders language plpgsql security definer set search_path=public as $$ declare r public.orders; begin if not public.has_staff_role(array['owner','superadmin','super_admin','sales_admin','admin']) then raise exception 'Not authorized'; end if; update public.orders set archived_at=null,archived_by=null,archive_reason=null,updated_by=auth.uid() where id=p_order_id and archived_at is not null returning * into r; if not found then raise exception 'Archived order not found'; end if; return r; end; $$; create or replace function public.permanently_delete_order(p_order_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_staff_role(array['owner','superadmin','super_admin']) then raise exception 'Only Super Admin can permanently delete order'; end if; delete from public.orders where id=p_order_id and archived_at is not null; if not found then raise exception 'Order must be archived before permanent deletion'; end if; end; $$; grant execute on function public.archive_order(uuid,text) to authenticated; grant execute on function public.restore_order(uuid) to authenticated; grant execute on function public.permanently_delete_order(uuid) to authenticated;;
